#!/usr/bin/env python3
import string, random, requests
def create_account(URL):
    endpoint = '/api/2.0/mlflow/users/create'
    username = ''.join(random.choices(string.ascii_uppercase + string.digits, k=10))
    password = ''.join(random.choices(string.ascii_uppercase + string.digits, k=10))
    data = requests.post(URL + endpoint, data={
        'username': username,
        'password': password
    })
    print(f'[i]\tCreating a user account with user ({username}), pw ({password})')
    if data.status_code != 200:
        print('Error creating account!')
        exit(0)
    print(f'returned: {data.text}')
    return (username, password)
if __name__ == '__main__':
    print(create_account('http://172.16.250.130:5000'))
